insert into passages (title,body,"wordCount",difficulty,topic,status) values ('Why Small Habits Matter', 'Large achievements often depend on repeated actions that seem minor at first. A learner who reviews ten words daily may not notice immediate progress, but the habit creates steady exposure and reduces the need for last-minute memorization. The value of a small habit is not its size; it is its consistency. When routines are realistic, people are more likely to maintain them long enough to see meaningful results. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 89, 7, 'habits and learning', 'approved');
